-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.duplicate_page(p_source_page uuid, p_expected_revision bigint)
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner,cms_authenticated_user=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.duplicate_page(p_source_page uuid, p_expected_revision bigint)
 RETURNS TABLE(page_id uuid, version_id uuid, revision bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid; source RECORD; draft RECORD; copied uuid; saved RECORD; base text; candidate text; suffix integer:=1; copied_title text; result_revision bigint;
BEGIN
 actor:=app.require_actor();SELECT * INTO source FROM public.pages WHERE id=p_source_page FOR UPDATE;
 IF source.id IS NULL OR source.archived_at IS NOT NULL THEN RAISE EXCEPTION 'This page is unavailable.' USING ERRCODE='CMS03';END IF;
 IF NOT app.can_publish(source.site_id) THEN RAISE EXCEPTION 'An editor can duplicate pages on this site.' USING ERRCODE='CMS02';END IF;
 IF source.revision IS DISTINCT FROM p_expected_revision THEN RAISE EXCEPTION 'The page changed. Save it before making a copy.' USING ERRCODE='CMS01',DETAIL=source.revision::text;END IF;
 SELECT v.* INTO draft FROM public.page_versions v WHERE v.id=COALESCE(source.draft_version_id,source.published_version_id) AND v.page_id=source.id;
 IF draft.id IS NULL THEN RAISE EXCEPTION 'Save this page before making a copy.' USING ERRCODE='CMS04';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(source.site_id::text,50));
 base:=trim(both '-' FROM regexp_replace(COALESCE(NULLIF(source.slug,''),'home'),'[^a-z0-9-]','-','g'));base:=left(base,145)||'-copy';candidate:=base;
 WHILE EXISTS(SELECT 1 FROM public.pages WHERE site_id=source.site_id AND slug=candidate) OR EXISTS(SELECT 1 FROM public.published_routes WHERE site_id=source.site_id AND path='/'||candidate) LOOP suffix:=suffix+1;candidate:=base||'-'||suffix;END LOOP;
 copied_title:=left('Copy of '||source.title,200);
 copied:=app.create_page(source.site_id,candidate,copied_title);
 SELECT * INTO saved FROM app.save_page_draft(copied,0,draft.content,draft.meta-'canonical','checkpoint','Copied from '||source.title);
 result_revision:=saved.revision;
 IF source.parent_page_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.pages WHERE id=source.parent_page_id AND archived_at IS NULL AND site_id=source.site_id) THEN result_revision:=app.set_page_parent(copied,result_revision,source.parent_page_id);END IF;
 PERFORM app.write_audit(source.site_id,'user',actor,'page.duplicate','page',copied,draft.id,saved.version_id,jsonb_build_object('source_page',source.id,'source_version',draft.id,'revision',result_revision));
 RETURN QUERY SELECT copied,saved.version_id,result_revision;
END $function$
